-- 001_init: the core tables of the platform.
--
-- Rules of the game:
--  * Every restaurant-owned table carries restaurant_id, so every query can (and must)
--    filter by it. That is what keeps one restaurant away from another one's data.
--  * Prices are integers in the smallest unit (cents for USD, whole pounds for LBP).
--    An integer avoids floating point errors such as 0.1 + 0.2.
--  * Secrets (passwords, invite tokens, email codes) are stored as hashes, never as-is.
--  * Do not edit this file after it has been applied. Add a new numbered migration instead.

CREATE TABLE restaurants (
  id          INTEGER GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  name        TEXT        NOT NULL CHECK (char_length(btrim(name)) BETWEEN 1 AND 80),
  -- Random, hard to guess part of the public link: /m/<public_slug>
  public_slug TEXT        NOT NULL UNIQUE CHECK (public_slug ~ '^[A-Za-z0-9_-]{12,40}$'),
  status      TEXT        NOT NULL DEFAULT 'active' CHECK (status IN ('active', 'suspended')),
  currency    TEXT        NOT NULL DEFAULT 'USD'    CHECK (currency IN ('USD', 'LBP')),
  phone       TEXT        NOT NULL DEFAULT '' CHECK (phone ~ '^\+?[0-9 ]{0,20}$'),
  whatsapp    TEXT        NOT NULL DEFAULT '' CHECK (whatsapp ~ '^\+?[0-9 ]{0,20}$'),
  map_url     TEXT        NOT NULL DEFAULT '' CHECK (map_url = '' OR map_url ~ '^https://'),
  created_at  TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE TABLE users (
  id                INTEGER GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  -- Stored in lowercase so "A@x.com" and "a@x.com" cannot be two accounts.
  email             TEXT        NOT NULL UNIQUE CHECK (email = lower(email) AND email LIKE '%_@_%'),
  password_hash     TEXT        NOT NULL,
  role              TEXT        NOT NULL CHECK (role IN ('super_admin', 'owner')),
  -- UNIQUE = one owner per restaurant. If the restaurant is deleted, its owner goes too.
  restaurant_id     INTEGER     UNIQUE REFERENCES restaurants(id) ON DELETE CASCADE,
  email_verified_at TIMESTAMPTZ,
  created_at        TIMESTAMPTZ NOT NULL DEFAULT now(),
  -- An owner always belongs to a restaurant; a super admin never does.
  CONSTRAINT role_matches_restaurant CHECK (
    (role = 'owner'       AND restaurant_id IS NOT NULL) OR
    (role = 'super_admin' AND restaurant_id IS NULL)
  )
);

CREATE TABLE invites (
  id         INTEGER GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  -- Hash of the random token inside the link. If the database leaks, the links stay unusable.
  token_hash TEXT        NOT NULL UNIQUE,
  -- Optional: restrict the invite to one email address.
  email      TEXT        CHECK (email IS NULL OR email = lower(email)),
  created_by INTEGER     NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  expires_at TIMESTAMPTZ NOT NULL,
  -- NULL until the sign-up is completed (email verified); then it can never be used again.
  used_at    TIMESTAMPTZ,
  used_by    INTEGER     REFERENCES users(id) ON DELETE SET NULL,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE TABLE email_codes (
  id         INTEGER GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  user_id    INTEGER     NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  -- verify_email now; reset_password later, with no new table.
  purpose    TEXT        NOT NULL CHECK (purpose IN ('verify_email', 'reset_password')),
  code_hash  TEXT        NOT NULL,
  expires_at TIMESTAMPTZ NOT NULL,
  -- Wrong guesses so far. The application invalidates the code after 5.
  attempts   INTEGER     NOT NULL DEFAULT 0 CHECK (attempts >= 0),
  -- Also used to limit how often a new code can be requested.
  created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX email_codes_lookup_idx ON email_codes (user_id, purpose, created_at DESC);

CREATE TABLE categories (
  id            INTEGER GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  restaurant_id INTEGER NOT NULL REFERENCES restaurants(id) ON DELETE CASCADE,
  name_ar       TEXT    NOT NULL CHECK (char_length(btrim(name_ar)) BETWEEN 1 AND 80),
  name_en       TEXT    NOT NULL CHECK (char_length(btrim(name_en)) BETWEEN 1 AND 80),
  sort_order    INTEGER NOT NULL DEFAULT 0 CHECK (sort_order >= 0),
  -- Lets child tables reference the PAIR (id, restaurant_id), see items below.
  UNIQUE (id, restaurant_id)
);
CREATE INDEX categories_menu_idx ON categories (restaurant_id, sort_order);

CREATE TABLE items (
  id            INTEGER GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  restaurant_id INTEGER NOT NULL REFERENCES restaurants(id) ON DELETE CASCADE,
  category_id   INTEGER NOT NULL,
  name_ar       TEXT    NOT NULL CHECK (char_length(btrim(name_ar)) BETWEEN 1 AND 80),
  name_en       TEXT    NOT NULL CHECK (char_length(btrim(name_en)) BETWEEN 1 AND 80),
  desc_ar       TEXT    NOT NULL DEFAULT '' CHECK (char_length(desc_ar) <= 300),
  -- Single price. NULL when the item has sizes (see item_sizes).
  -- "Either a price or at least 2 sizes" is checked by the application: SQL cannot
  -- express a rule that spans two tables with a simple CHECK.
  price_minor   INTEGER CHECK (price_minor >= 0),
  image_url     TEXT    CHECK (image_url IS NULL OR image_url ~ '^https://'),
  sort_order    INTEGER NOT NULL DEFAULT 0 CHECK (sort_order >= 0),
  -- The category must belong to the SAME restaurant as the item. The database itself
  -- refuses an item that points to another restaurant's category.
  FOREIGN KEY (category_id, restaurant_id)
    REFERENCES categories (id, restaurant_id) ON DELETE CASCADE,
  UNIQUE (id, restaurant_id)
);
CREATE INDEX items_category_idx ON items (category_id, sort_order);

CREATE TABLE item_sizes (
  id            INTEGER GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  restaurant_id INTEGER NOT NULL REFERENCES restaurants(id) ON DELETE CASCADE,
  item_id       INTEGER NOT NULL,
  -- Short, chosen by the owner: S, M, L, XL, XXL...
  label         TEXT    NOT NULL CHECK (label ~ '^[A-Za-z0-9]{1,6}$'),
  price_minor   INTEGER NOT NULL CHECK (price_minor >= 0),
  sort_order    INTEGER NOT NULL DEFAULT 0 CHECK (sort_order >= 0),
  FOREIGN KEY (item_id, restaurant_id)
    REFERENCES items (id, restaurant_id) ON DELETE CASCADE,
  UNIQUE (item_id, label)
);
